#!/usr/bin/env bash
# MXBMRP3 1.35.0 (source public on GitHub under the MIT licence: the release files and the source).
# The folder holds the three files of https://github.com/thomas4f/mxbmrp3/releases/tag/v1.35.0, by their names:
# mxbmrp3.zip, mxbmrp3-Setup.exe and mxbmrp3.cdx.json. This script unpacks the zip into zip/ and Setup (NSIS) into setup/.
# The second argument is a checkout of https://github.com/thomas4f/mxbmrp3 at 64f3f33db2bb3e0df41649159bceae309a2a0b68
# (tag v1.35.0), with its history.
# Needs GNU binutils, file, unzip, 7-Zip (7z), python3, and for release-api and attestation the network and the
# sigstore Python package (pip install sigstore; set SIGSTORE to its python, default python3).
. "$(dirname "$0")/../ev.sh"
(cd "$R" && rm -rf zip setup && mkdir zip setup && unzip -q -d zip mxbmrp3.zip && 7z x -y -osetup mxbmrp3-Setup.exe > /dev/null)
ev files "sha256sum mxbmrp3.zip mxbmrp3-Setup.exe mxbmrp3.cdx.json zip/mxbmrp3.dlo zip/mxbmrp3_gpb.dlo zip/mxbmrp3_krp.dlo zip/README.txt zip/LICENSE zip/THIRD_PARTY_LICENSES.md setup/mxbmrp3_uninstall.exe 'setup/\$PLUGINSDIR/System.dll' 'setup/\$PLUGINSDIR/nsDialogs.dll'; echo '--- files in the zip:'; unzip -l mxbmrp3.zip | tail -1"
ev file "file mxbmrp3-Setup.exe zip/*.dlo setup/mxbmrp3_uninstall.exe setup/\\\$PLUGINSDIR/*.dll; echo '--- every other file in the zip is data (fonts, images, text, web page):'; find zip -type f ! -name '*.dlo' -exec file -b {} + | sed 's/,.*//' | sort | uniq -c"
# Setup is NSIS 3.09; it holds the same three plugins as the zip, byte for byte, and the same data folder (it adds
# LICENSE and THIRD_PARTY_LICENSES.md inside mxbmrp3_data and leaves out the zip's README and a .gitkeep).
ev setup "strings -n 8 mxbmrp3-Setup.exe | grep -o 'Nullsoft Install System v[0-9.-]*' | head -1; 7z l mxbmrp3-Setup.exe | grep -E '\\.(dlo|exe|dll)\$'; sha256sum zip/*.dlo setup/\\\$_2*_/*.dlo; diff -r 'setup/\$_21_/mxbmrp3_data' zip/mxbmrp3_data"
ev mxbmrp3.dlo.objdump-p "objdump -p zip/mxbmrp3.dlo | awk '/^The Function Table|^PE File Base Relocations/{exit} 1'"
ev mxbmrp3.dlo.objdump-h "objdump -h zip/mxbmrp3.dlo"
ev mxbmrp3.dlo.iat "iat.py zip/mxbmrp3.dlo"
ev signature "objdump -p mxbmrp3-Setup.exe zip/mxbmrp3.dlo zip/mxbmrp3_gpb.dlo zip/mxbmrp3_krp.dlo setup/mxbmrp3_uninstall.exe | grep -E 'file format|Security Directory'"
# The GitHub build-provenance attestations of the release files, fetched from GitHub's API and checked with sigstore
# against the release workflow of thomas4f/mxbmrp3 at the commit; then the same check on a changed copy of the zip.
ev attestation "for h in 0b2d7654d3e830cc192fd3e1cc8eb71342b9ce3e03f73eb62b7918959abebe80 4a30fbd20b01b1c22b962c8ea16e6bc4617ac1e42447b668edc174dcb3324dc9; do curl -sS https://api.github.com/repos/thomas4f/mxbmrp3/attestations/sha256:\$h | python3 -I -c 'import json,sys; print(json.dumps(json.load(sys.stdin)[\"attestations\"][0][\"bundle\"]))' > \"\$W/\$h.json\"; done; for p in mxbmrp3.zip:0b2d7654d3e830cc192fd3e1cc8eb71342b9ce3e03f73eb62b7918959abebe80 mxbmrp3-Setup.exe:4a30fbd20b01b1c22b962c8ea16e6bc4617ac1e42447b668edc174dcb3324dc9; do f=\${p%%:*}; h=\${p##*:}; \${SIGSTORE:-python3} -m sigstore verify github --bundle \"\$W/\$h.json\" --repository thomas4f/mxbmrp3 --sha 64f3f33db2bb3e0df41649159bceae309a2a0b68 --name release --trigger workflow_dispatch --ref refs/heads/main \$f 2>&1 | grep -E '^OK|FAIL' ; done; python3 -I -c 'import json,sys,base64; b=json.load(open(sys.argv[1])); s=json.loads(base64.b64decode(b[\"dsseEnvelope\"][\"payload\"])); [print(\"subject\", x[\"name\"], x[\"digest\"][\"sha256\"]) for x in s[\"subject\"]]; print(\"workflow\", s[\"predicate\"][\"buildDefinition\"][\"externalParameters\"][\"workflow\"][\"path\"], \"commit\", s[\"predicate\"][\"buildDefinition\"][\"resolvedDependencies\"][0][\"digest\"][\"gitCommit\"], \"run\", s[\"predicate\"][\"runDetails\"][\"metadata\"][\"invocationId\"])' \"\$W/0b2d7654d3e830cc192fd3e1cc8eb71342b9ce3e03f73eb62b7918959abebe80.json\"; echo '--- a changed copy of the zip:'; cp mxbmrp3.zip \"\$W/changed.zip\"; printf x >> \"\$W/changed.zip\"; cd \"\$W\" && \${SIGSTORE:-python3} -m sigstore verify github --bundle 0b2d7654d3e830cc192fd3e1cc8eb71342b9ce3e03f73eb62b7918959abebe80.json --repository thomas4f/mxbmrp3 --name release changed.zip 2>&1 | grep -oE 'FAIL: changed.zip|OK: changed.zip'"
# The release on GitHub: who uploaded the files, and the release workflow run at the commit (network).
ev release-api "curl -sS https://api.github.com/repos/thomas4f/mxbmrp3/releases/tags/v1.35.0 | python3 -I -c 'import json,sys; d=json.load(sys.stdin); print(\"release\", d[\"tag_name\"], \"author\", d[\"author\"][\"login\"], \"published\", d[\"published_at\"]); [print(a[\"name\"], \"uploaded by\", a[\"uploader\"][\"login\"], a[\"digest\"], a[\"updated_at\"]) for a in d[\"assets\"]]'; curl -sS 'https://api.github.com/repos/thomas4f/mxbmrp3/actions/runs?head_sha=64f3f33db2bb3e0df41649159bceae309a2a0b68' | python3 -I -c 'import json,sys; [print(r[\"name\"], r[\"event\"], r[\"head_branch\"], r[\"head_sha\"], r[\"conclusion\"], r[\"created_at\"], r[\"html_url\"]) for r in json.load(sys.stdin)[\"workflow_runs\"] if r[\"name\"] == \"release\"]'"
# What the plugin imports: network (WinHTTP, Winsock), the crash handler, registry reads only, OpenProcess, key and
# window reads, ShellExecute; and what it doesn't.
ev imports-dlo "objdump -p zip/mxbmrp3.dlo | grep 'DLL Name'; iat.py zip/mxbmrp3.dlo | grep -E 'SetUnhandledExceptionFilter|OpenProcess|VirtualProtect|GetAsyncKeyState|GetForegroundWindow|ShellExecuteA|RegGetValueA|RegQueryValueExA|RegOpenKeyExA|WinHttpOpen\$|WinHttpConnect|WinHttpWebSocketCompleteUpgrade|WS2_32.dll!(bind|listen|accept)\$|XInputSetState|MiniDumpWriteDump|GetProcAddress\$|GetModuleHandleA\$'; echo '--- absent:'; iat.py zip/mxbmrp3.dlo | grep -E 'RegSetValue|RegCreateKey|RegDeleteKey|WriteProcessMemory|ReadProcessMemory|VirtualAllocEx|CreateRemoteThread|SetWindowsHookEx|SendInput|keybd_event|mouse_event|CreateProcess|WinExec|AddVectoredExceptionHandler|SetWindowLongPtr' || echo 'none of: registry writes, Read/WriteProcessMemory, VirtualAllocEx, CreateRemoteThread, SetWindowsHookEx, SendInput, keybd_event, mouse_event, CreateProcess, WinExec, AddVectoredExceptionHandler, SetWindowLongPtr'; echo '--- the GP Bikes and Kart Racing Pro plugins import the same:'; for f in zip/mxbmrp3_gpb.dlo zip/mxbmrp3_krp.dlo; do diff <(objdump -p zip/mxbmrp3.dlo | grep 'DLL Name') <(objdump -p \$f | grep 'DLL Name') > /dev/null && echo \"\$f: same DLLs\"; done"
# The plugin's three VirtualProtect calls (IAT slot 0x1802ff388) all take its own .fptable section (0x18042a000,
# 0x100 bytes), a table of the statically linked MSVC C runtime, not the game's code.
ev virtualprotect "objdump -h zip/mxbmrp3.dlo | grep -E 'fptable'; objdump -d zip/mxbmrp3.dlo | grep -E '# 0x1802ff388|# 0x18042a000'"
# The source has no memory writing, hooking, injection or key sending outside the vendored libraries.
ev src-memory "cd \"\$SRC/mxbmrp3\" && grep -rnE 'WriteProcessMemory|ReadProcessMemory|VirtualProtect|VirtualAllocEx|CreateRemoteThread|SetWindowsHookEx|SendInput|keybd_event|mouse_event|SetWindowLongPtr|RegSetValue|RegCreateKey|CreateProcess' --include=*.cpp --include=*.h . | grep -v '^./vendor/' | grep -vE ':[0-9]+:\\s*//' || echo 'none outside comments'; echo '--- OpenProcess (media player name only) and the camera list, which comes from the SpectateCameras callback:'; grep -n 'OpenProcess(' core/media_manager.cpp; grep -n 'SpectateCameras' handlers/camera_resolve.h | head -2"
ev strings-urls "for f in zip/mxbmrp3.dlo; do strings -n 6 \$f | grep -oE 'https?://[A-Za-z0-9./{}_?=%-]+' | sort -u; strings -n 6 \$f | grep -oE '[a-z0-9.-]+\\.(goatcounter|aptabase|githubusercontent|github)\\.com|api\\.github\\.com|[a-z.]*twitch\\.tv|youtube\\.com|cbrservers\\.com|mxb-ranked\\.com' | sort -u; done"
# Usage survey: on by default (opt-out), what app_started carries, the install ID, GoatCounter, the remote config
# (fetched only while the survey is on), the crash summary, and Setup's checkbox (ticked by default).
ev src-analytics "cd \"\$SRC\" && grep -n 'm_enabled(true)' mxbmrp3/core/analytics_manager.cpp; grep -nE '(props|sys|p|r)\\[\"[a-z_A-Z]+\"\\] =' mxbmrp3/core/analytics_manager.cpp | cut -c1-140; grep -nE 'hit\\[\"(path|session)\"\\]' mxbmrp3/core/analytics_manager.cpp; grep -nE 'aptabase.com' mxbmrp3/core/analytics_endpoint.h; grep -nE 'ANALYTICS_CONFIG_(HOST|FILE)|ONLY if analytics' mxbmrp3/core/plugin_constants.h; grep -nE 'POST\", L\"/api/v0/(events|count)' mxbmrp3/core/analytics_manager_transport.cpp; grep -nE 'analyticsOptOut \"0\"|NSD_CreateCheckbox.*usage survey|NSD_Check \\\$analyticsCheckbox' packaging/mxbmrp3.nsi"
# Update check: Notify by default, at start; the download only from GitHub hosts and checked against GitHub's
# SHA-256 digest; the backup moves only the plugin's own files.
ev src-update "cd \"\$SRC/mxbmrp3/core\" && grep -nE 'm_mode\\(UpdateMode::NOTIFY\\)' update_checker.cpp; grep -nE 'checking for updates on startup|checkForUpdates\\(\\);' settings_manager.cpp; grep -nE '/releases\\?per_page|\"digest\"|sha256:' update_checker.cpp; grep -nE 'host == \"github.com\"|githubusercontent.com\"|SHA256 checksum mismatch|installing on TLS trust alone' update_downloader.cpp; grep -nE 'dloDst = backupDir|dataDst = backupDir|find\\(\"\\.\\.\"\\)|deleteDirectoryRecursive\\(backupDir\\)' update_downloader_install.cpp; grep -rnE 'UPDATE_BACKUP_DIR|mxbmrp3_update_backup' . | grep -v test | head -3"
# Every place the plugin connects to, and its local web server: off by default, 127.0.0.1:8080, any website may read it.
ev src-network "cd \"\$SRC/mxbmrp3/core\" && grep -nE 'GITHUB_API_HOST|records/top|mxb-ranked.com|irc-ws.chat.twitch.tv|youtube.com/|discord-ipc' *.cpp *.h | grep -v test | cut -c1-160 | head -20; echo '--- web overlay:'; grep -nE 'm_enabled\\(false\\)|Access-Control-Allow-Origin|set_mount_point|listen\\(bindAddr' http_server.cpp; grep -nE 'DEFAULT_BIND_ADDRESS = |DEFAULT_PORT = ' http_server.h; echo '--- off by default: Discord, Records HUD, Stream Chat HUD:'; grep -n 'm_enabled(false)' discord_manager.cpp; grep -n 'm_bVisible = false;' ../hud/records_hud.cpp ../hud/stream_chat_hud.cpp"
# Steam: on by default; publishes your track, server and session as rich presence and reads your friends' names
# and presence through the game's own steam_api64.dll.
ev src-steam "cd \"\$SRC/mxbmrp3/core\" && grep -nE 'm_enabled\\(true\\)|GetModuleHandleA\\(\"steam_api64.dll\"\\)|SetRichPresence\"|GetFriendPersonaName\"|GetFriendRichPresence\"|fe.name    = name|strncpy_s\\(inputs.(trackName|serverName)|No persona name, no' steam_friends_manager.cpp"
ev src-keys "cd \"\$SRC/mxbmrp3/core\" && grep -nE 'GetAsyncKeyState|isCursorEnabled\\(\\)\\) \\{|Always update previous input|foregroundPid == m_processId|if \\(m_bCursorEnabled\\) \\{' hotkey_manager.cpp input_manager.cpp | head -40; grep -nE 'VK_OEM_3|VK_NEXT|VK_PRIOR' hotkey_config.h | head -5"
ev src-crash "cd \"\$SRC/mxbmrp3/core\" && grep -nE 'SetUnhandledExceptionFilter|return s_previousFilter\\(info\\)|EXCEPTION_CONTINUE_SEARCH;|crashes\\\\\\\\mxbmrp3_crash|MiniDumpWriteDump\\(' crash_handler.cpp | head -12"
# Setup and the uninstaller: what they write, delete and put in the registry.
ev src-installer "cd \"\$SRC\" && grep -nE '^\\s*(Delete|RMDir|WriteReg|DeleteReg|ExecWait|CopyFiles|WriteUninstaller|File )' packaging/mxbmrp3.nsi | cut -c1-150; grep -nE 'Removing settings and data|remove all data|uninstaller leaves it' packaging/mxbmrp3.nsi README.md | head -5"
# The usage survey's per-install data is published in the repository: one row per install (a hash of its install
# ID, last ping time, game, version, country, Windows version, features and achievements) and, per month, every
# launch hour and session length per install.
ev survey-published "cd \"\$SRC\" && git ls-files usage_survey/rollup; echo '--- installs.csv.gz: header columns 1-7, rows:'; zcat usage_survey/rollup/installs.csv.gz | head -1 | cut -d, -f1-7; zcat usage_survey/rollup/installs.csv.gz | tail -n +2 | wc -l; echo '--- 2026-11.csv.gz: header, rows:'; zcat usage_survey/rollup/2026-11.csv.gz | head -1; zcat usage_survey/rollup/2026-11.csv.gz | tail -n +2 | wc -l; echo '--- how the install column is made:'; grep -nE 'blake2s|REPLACED by' tools/analytics_rollup.py; echo '--- what the README says is published:'; grep -nE 'aggregate results are published' README.md | cut -c1-200"
ev deps "cd \"\$SRC\" && grep -nE 'runs-on:|uses: |install_deps.sh nsis|APTABASE_KEY: |GOATCOUNTER_TOKEN: |workflow_dispatch:|actions/attest' .github/workflows/release.yml; python3 -I -c 'import json,sys; [print(d[\"name\"], d[\"version\"], \"shipped\" if d[\"shipped\"] else \"not shipped\") for d in json.load(open(sys.argv[1]))[\"deps\"]]' mxbmrp3/vendor/vendored.json; grep -nE 'error \"Release build is missing analytics keys' mxbmrp3/core/plugin_constants.h"
ev repo-files "cd \"\$SRC\" && git ls-files | grep -iE '^LICENSE|THIRD_PARTY'; head -3 LICENSE; echo '--- prebuilt program files:'; git ls-files | grep -iE '\\.(dll|lib|exe|dlo|so|wasm|pyc|o|obj|node|jar)\$' || echo none; echo '--- history:'; git log --oneline 64f3f33db2bb3e0df41649159bceae309a2a0b68 | wc -l; git log --format='%ad %s' --date=short 64f3f33db2bb3e0df41649159bceae309a2a0b68 | sed -n '1,3p;\$p'; git log --format='%s' 64f3f33db2bb3e0df41649159bceae309a2a0b68 | sed 's/ v[0-9.]*\$//' | sort | uniq -c; grep -nE 'squashed tree|as ONE commit' .github/workflows/mirror.yml usage_survey/README.md | head -3"
ev strings-thirdparty "grep -nE '^#+ ' zip/THIRD_PARTY_LICENSES.md | head -40; for f in THIRD_PARTY_LICENSES.md LICENSE; do cmp -s <(tr -d '\\r' < zip/\$f) <(tr -d '\\r' < \"\$SRC/\$f\") && echo \"zip/\$f = \$f at the commit, apart from line endings\" || echo \"DIFFERENT: \$f\"; done"
ev donations "cd \"\$SRC\" && cat .github/FUNDING.yml; grep -nE 'ko-fi.com' mxbmrp3/hud/settings/settings_links.cpp README.md; grep -nE 'no paid tier|thanks links on the About page' docs/what-it-does.md | cut -c1-220"
money zip/mxbmrp3.dlo zip/README.txt
